"""읽기·근거 선택·판단을 연결하는 게임 내부 조사 화면."""
import json
from investigation_content import CASES
JS = "\nconst IQ_STATE={};\nfunction iqState(i){return IQ_STATE[i]||(IQ_STATE[i]={seen:[],selected:[],choice:'',view:null,done:false,error:'',hints:0,tries:0});}\nfunction iqMark(t){const C={'가':'#DBEAFE;color:#1E40AF;border-color:#60A5FA','나':'#FEF3C7;color:#92400E;border-color:#FBBF24','다':'#DCFCE7;color:#166534;border-color:#4ADE80','라':'#F3E8FF;color:#6B21A8;border-color:#C084FC'};return esc(t).replace(/익명 판매자 ([가나다라])/g,(m,k)=>'<b style=\"border:2px solid;background:'+C[k]+';padding:1px 8px;border-radius:999px;white-space:nowrap;font-weight:900\">🕵️ 익명 판매자 '+k+'</b>');}\nfunction iqSource(source){\n // 게임마다 자료를 보여 주는 모양이 달라요: 중고거래는 '도토리마켓' 앱 화면, 노노그램은 감식 자료 카드.\n const th=(typeof IQ_THEME!=='undefined')?IQ_THEME:'';\n if(th==='market') return `<article style=\"max-width:460px;margin:14px auto;background:#1F2937;border-radius:30px;padding:10px;box-shadow:0 10px 24px #0004\"><div style=\"background:#FFF7ED;border-radius:22px;overflow:hidden\"><div style=\"background:#F97316;color:#fff;padding:10px 14px;font-weight:900\">🛍️ 도토리마켓 · ${iqMark(source[1])}</div><div style=\"padding:12px 14px\"><div style=\"background:#fff;border-radius:4px 16px 16px 16px;padding:10px 12px;box-shadow:0 1px 3px #0002;font-size:1.05rem;line-height:1.75\">${iqMark(source[2])}</div></div></div></article>`;\n if(th==='lab') return `<article style=\"position:relative;margin:16px 0;background:#FFFDF5;border:1px solid #E5DCC3;border-radius:6px;padding:16px 16px 12px;box-shadow:0 6px 14px #0002;transform:rotate(-.6deg)\"><span style=\"position:absolute;top:-10px;left:18px;background:#FDE68A;border:1px solid #E7C55A;padding:2px 10px;font-weight:900;font-size:.85rem;transform:rotate(-3deg)\">🏷️ 감식 자료</span><b style=\"font-size:1.05rem\">${iqMark(source[1])}</b><p style=\"font-size:1.05rem;line-height:1.75;margin:.5rem 0 0\">${iqMark(source[2])}</p></article>`;\n return `<article style=\"background:#f0f5f2;padding:14px;margin:12px 0;border-left:5px solid #39756b\"><b style=\"font-size:1.05rem\">${iqMark(source[1])}</b><p style=\"font-size:1.05rem;line-height:1.75;margin:.5rem 0 0\">${iqMark(source[2])}</p></article>`;\n}\nfunction iqHTML(i){\n const c=IQ_CASES[i],s=iqState(i);\n const source=c.sources.find(x=>x[0]===s.view);\n return `<section class=\"box\" style=\"border:2px solid #b9d2c7;border-radius:16px;padding:16px;margin:12px 0;overflow-wrap:anywhere\">\n <h3>${esc(c.title)}</h3><div style=\"display:flex;flex-wrap:wrap;gap:6px;margin:4px 0 10px;font-size:.92rem;font-weight:800\"><span style=\"background:#EAF6F0;border-radius:999px;padding:3px 10px\">① 자료 버튼을 눌러 읽기</span><span style=\"background:#EAF6F0;border-radius:999px;padding:3px 10px\">② 아래에서 결론 고르기</span><span style=\"background:#EAF6F0;border-radius:999px;padding:3px 10px\">③ 결론을 보여 주는 자료 ${c.proof.length}개 체크</span><span style=\"background:#EAF6F0;border-radius:999px;padding:3px 10px\">④ 제출</span></div><p style=\"margin:0 0 8px;font-size:.92rem;color:#475569\">🔒 표시가 있는 자료는 앞 자료를 읽으면 열려요. 헷갈리라고 넣은 자료도 섞여 있어요.</p>\n <div style=\"display:flex;gap:8px;flex-wrap:wrap\">${c.sources.map(x=>`<button onclick=\"iqOpen(${i},'${x[0]}')\" ${x[3]&&!s.seen.includes(x[3])?'disabled':''}>${s.seen.includes(x[0])?'✓ ':''}${iqMark(x[1])}${x[3]&&!s.seen.includes(x[3])?' 🔒 앞 자료를 먼저 읽기':''}</button>`).join('')}</div>\n ${source?iqSource(source):''}\n ${s.done?iqSolution(c):`\n <p><b>${esc(c.question)}</b></p>\n <select aria-label=\"조사 ${i+1} 결론\" onchange=\"iqState(${i}).choice=this.value;render()\" style=\"width:100%;font:inherit;padding:10px;white-space:normal\"><option value=\"\">👇 결론을 하나 고르세요</option>${c.options.map((v,k)=>`<option value=\"${k}\" ${String(k)===s.choice?'selected':''}>${esc(v)}</option>`).join('')}</select>\n ${s.choice!==''?'<p><b>선택한 결론:</b> '+esc(c.options[Number(s.choice)])+'</p>':''}\n <p style=\"margin-bottom:2px\"><b>이 결론을 직접 뒷받침하는 자료 ${c.proof.length}개 선택</b></p>\n <p style=\"margin:0 0 6px;background:#EFF6FF;border-left:4px solid #60A5FA;border-radius:6px;padding:6px 10px;font-size:.92rem\">📌 위에서 <b>눌러서 읽은 자료만</b> 여기에 체크칸으로 나와요. (읽은 자료 ${s.seen.length} / ${c.sources.length})${s.seen.length<c.sources.length?' 아직 안 읽은 자료가 있다면 위의 자료 버튼을 먼저 눌러 보세요.':''}</p>\n ${s.seen.length?'<div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px;margin:6px 0 10px\">'+c.sources.filter(x=>s.seen.includes(x[0])).map(x=>{const on=s.selected.includes(x[0]);return `<label style=\"display:flex;align-items:center;gap:10px;padding:10px 12px;border:2px solid ${on?'#16A34A':'#D6DDE2'};border-radius:14px;background:${on?'#F0FDF4':'#fff'};cursor:pointer;font-weight:${on?800:600};box-shadow:${on?'0 3px 8px #16A34A33':'0 1px 3px #0001'};transition:all .15s\"><input type=\"checkbox\" ${on?'checked':''} onchange=\"iqSelect(${i},'${x[0]}',this.checked)\" style=\"width:20px;height:20px;accent-color:#16A34A;flex:0 0 auto\"><span style=\"line-height:1.4\">${on?'✅ ':''}${iqMark(x[1])}</span></label>`;}).join('')+'</div>'+`<div style=\"font-size:.9rem;font-weight:800;color:${s.selected.length===c.proof.length?'#166534':'#64748B'};margin:-4px 0 8px\">☑️ 선택 ${s.selected.length} / ${c.proof.length}${s.selected.length===c.proof.length?' · 이제 제출해 보세요!':''}</div>`:'<p>아직 읽은 자료가 없어요. 위의 자료 버튼을 눌러 먼저 읽어 보세요.</p>'}\n <button onclick=\"iqCheck(${i})\">근거와 결론 제출</button> <button onclick=\"iqHint(${i})\" ${s.hints>=iqHintList(c).length?'disabled':''}>💡 비교할 지점 힌트 (${Math.min(s.hints,iqHintList(c).length)}/${iqHintList(c).length})</button>\n <p role=\"status\" style=\"color:#9b361d;font-weight:700\">${esc(s.error)}</p>\n ${s.hints?'<div style=\"background:#FFFBEB;border:2px solid #FCD34D;border-radius:12px;padding:8px 12px;margin-top:6px;line-height:1.7\">'+iqHintList(c).slice(0,s.hints).map((h,k)=>'<div><b>힌트 '+(k+1)+'</b> · '+esc(h)+'</div>').join('')+'</div>':''}`}\n </section>`;\n}\nfunction iqOpen(i,k){const c=IQ_CASES[i],s=iqState(i),x=c.sources.find(x=>x[0]===k);if(!x||(x[3]&&!s.seen.includes(x[3])))return;if(!s.seen.includes(k))s.seen.push(k);s.view=k;render();}\nfunction iqSelect(i,k,on){const s=iqState(i);s.selected=s.selected.filter(x=>x!==k);if(on&&s.seen.includes(k))s.selected.push(k);render();}\nfunction iqHintList(c){return c.hints&&c.hints.length?c.hints:[c.hint];}\n// 다 풀면 정답 결론과 자료마다 왜 근거인지/아닌지를 풀이로 보여 줘요.\nfunction iqSolution(c){\n // 풀이를 1단계(자료 읽기) → 2단계(결론) → 3단계(근거)로 나눠 보여 줘요.\n const rows=c.sources.map(x=>{const ok=c.proof.includes(x[0]);return '<tr><td style=\"padding:6px 8px;white-space:nowrap;font-weight:800;color:'+(ok?'#166534':'#9A3412')+'\">'+(ok?'✅ 근거':'❌ 아님')+'</td><td style=\"padding:6px 8px\"><b>'+iqMark(x[1])+'</b><br>'+esc((c.why||{})[x[0]]||'')+'</td></tr>';}).join('');\n const step=(n,t,body)=>'<div style=\"margin-top:10px\"><div style=\"font-weight:900;color:#166534\"><span style=\"display:inline-block;background:#166534;color:#fff;border-radius:999px;padding:0 9px;margin-right:6px\">'+n+'단계</span>'+t+'</div><div style=\"margin-top:6px\">'+body+'</div></div>';\n const proofs=c.sources.filter(x=>c.proof.includes(x[0])).map(x=>'<b>'+iqMark(x[1])+'</b>').join(', ');\n return '<div style=\"background:#ECFDF3;border:2px solid #86EFAC;border-radius:14px;padding:12px 14px;margin-top:8px;line-height:1.7\"><b style=\"font-size:1.1rem;color:#166534\">✓ 근거 연결 완료 · 📖 단계별 풀이</b>'\n +step(1,'자료 읽기 · 무엇이 근거이고 무엇이 아닐까?','<table style=\"width:100%;border-collapse:collapse;background:#fff;border-radius:10px;overflow:hidden;font-size:.95rem\">'+rows+'</table>')\n +step(2,'결론 고르기','<b>“'+esc(c.options[c.answer])+'”</b>'+(c.chain?'<br>👉 '+esc(c.chain):''))\n +step(3,'근거 체크하고 제출',proofs+'에 체크하면 결론이 한 줄로 이어져요.')\n +'<div style=\"margin-top:10px;background:#fff;border-radius:10px;padding:8px 12px\">💬 <b>핵심 요령</b> · '+esc(c.lesson)+'</div></div>';}\nfunction iqHint(i){const c=IQ_CASES[i],s0=iqState(i);if(s0.hints>=iqHintList(c).length)return;iqState(i).hints++;if(typeof iqHintUsed==='function')iqHintUsed(i);render();}\nfunction iqCheck(i){const s=iqState(i),c=IQ_CASES[i];if(s.done)return;\n if(s.choice===''){s.error='👇 먼저 결론을 하나 골라 주세요.';render();return;}\n if(s.selected.length!==c.proof.length){s.error='☑️ 근거 자료를 정확히 '+c.proof.length+'개 체크해 주세요. (지금 '+s.selected.length+'개)';render();return;}\n s.tries++;\n const ok=Number(s.choice)===c.answer&&c.proof.every(k=>s.seen.includes(k)&&s.selected.includes(k));\n if(ok){s.done=true;s.error='';iqComplete(i);}\n else{const okChoice=Number(s.choice)===c.answer;\n  // 결론이 틀렸는지, 근거가 틀렸는지 나눠서 알려 줘요(정답은 알려 주지 않아요).\n  s.error=okChoice?'👍 결론은 맞았어요! 다만 고른 근거가 달라요. 결론을 직접 보여 주는 자료만 남기고, 다른 판매자의 자료나 겉모습·말만 있는 자료는 빼 보세요.':'🤔 결론이 아직 맞지 않아요. 체크한 자료들을 순서대로 이어 보면 무슨 일이 있었는지 다시 생각해 보세요. 막히면 💡 힌트를 눌러 보세요.';if(typeof iqWrong==='function')iqWrong(i);render();}\n}\nfunction iqReset(){for(const k of Object.keys(IQ_STATE))delete IQ_STATE[k];}\n"
def attach(html):
    payload=json.dumps(CASES,ensure_ascii=False).replace("<","\\u003c")
    return html.replace("<script>", "<script>\nconst IQ_CASES="+payload+";\n"+JS+"\n",1)
